INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (10, 50, 'theory', 'Quiz: WebSockets and fan-out');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 50, 0, 'What status code does the server answer with to a successful Upgrade to WebSocket?', '["200 OK", "101 Switching Protocols", "204 No Content", "301 Moved"]', 1, '101 means switching to another protocol; after that, WebSocket frames flow over the same connection.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 50, 1, 'Why is the socket split into a receiver and a sender, with two tasks?', '["It is faster", "Reading commands and sending events are independent activities and must not block each other", "The protocol requires it", "To encrypt the traffic"]', 1, 'One task waits for client messages, the other for events from the channel; when either ends, both must stop.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 50, 2, 'What does a broadcast channel receiver get if it falls too far behind?', '["The program panics", "A Lagged error with the number of skipped messages", "All the messages again", "The channel is closed"]', 1, 'Old events are evicted; the client learns about the loss and has to catch up on history with a request.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 50, 3, 'In what order should a new message be written and broadcast?', '["Broadcast first, then write", "Write to the database first (get the id), then broadcast", "In parallel, in no particular order", "Broadcast only"]', 1, 'A client that received an event will always find the message in the history; broadcasting is the fast path, the database is the source of truth.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 50, 4, 'How do you tell that a user is offline if they have several connections?', '["By their last message", "The counter of their active connections reached zero", "By IP address", "You can''t"]', 1, 'Presence is counted by the number of the user''s active connections.');
